"""Deep Agents candidate, loaded only inside the solver sandbox."""

import os
import time
from pathlib import Path

from deepagents import (
    GeneralPurposeSubagentProfile,
    HarnessProfile,
    create_deep_agent,
    register_harness_profile,
)
from deepagents.backends import LocalShellBackend
from langchain_core.messages import AIMessage

from answer_space import answers_agree, ground_reply, load_answer_space, panel_winner
from tools import build_tools

SYSTEM_PROMPT = "You are an agent that answers a question by retrieving examples."
SKILL_PATH = "/harness/skills/answer-with-examples/SKILL.md"

# One reply is one draw from the model's own answer distribution, and on the questions where
# that distribution is wide a single draw is close to a coin flip.  The harness therefore asks
# the same question several times and answers with the reply the panel agrees on.
PANEL_SIZE = 5
# A unanimous panel of three has already settled on an answer, so later attempts are skipped.
PANEL_MINIMUM = 3
# Attempts stop being started once this share of the sample's own time budget is spent; a
# panel cut short still answers with the replies it has.
PANEL_BUDGET = 0.5


class GroundedAgent:
    """Ground each reply in the memory's answer space, then answer with the panel's choice."""

    def __init__(self, agent, space: dict, panel_size: int = PANEL_SIZE, budget: float | None = None):
        self._agent = agent
        self._space = space
        self._panel_size = panel_size
        self._budget = budget

    def __getattr__(self, name):
        return getattr(self._agent, name)

    def invoke(self, inputs, config=None, **kwargs):
        started = time.monotonic()
        results: list = []
        replies: list[str] = []
        while len(results) < self._panel_size:
            if results and self._spent(started):
                break
            try:
                result = self._agent.invoke(self._restart(inputs), config=config, **kwargs)
            except Exception:
                # A panel that ran out of time or out of model calls still votes.
                if not results:
                    raise
                break
            grounded = self._grounded(result)
            if grounded is None:
                return results[0] if results else result
            result, reply = grounded
            results.append(result)
            replies.append(reply)
            if len(replies) >= PANEL_MINIMUM and answers_agree(replies):
                break
        return results[panel_winner(replies)]

    def _grounded(self, result):
        """The attempt's result with its reply grounded, and the reply that vote compares."""
        messages = list(result.get("messages") or [])
        if not messages:
            return None
        last = messages[-1]
        content = last.content
        if isinstance(content, list):
            content = "".join(
                block if isinstance(block, str) else block.get("text", "")
                for block in content if isinstance(block, (str, dict))
            )
        if not isinstance(content, str):
            return None
        grounded = ground_reply(content, self._space)
        if grounded != content:
            messages[-1] = self._copy(last, grounded)
            result["messages"] = messages
        return result, grounded

    def _spent(self, started: float) -> bool:
        return self._budget is not None and time.monotonic() - started > self._budget

    @staticmethod
    def _restart(inputs):
        """A fresh copy of the inputs: every attempt is an independent run."""
        if not isinstance(inputs, dict):
            return inputs
        return {**inputs, "messages": [dict(message) for message in inputs.get("messages", [])]}

    @staticmethod
    def _copy(message, content: str):
        try:
            return message.model_copy(update={"content": content})
        except AttributeError:
            return AIMessage(content=content)


def build_agent(model, input_text: str, config: dict):
    profile = HarnessProfile(
        general_purpose_subagent=GeneralPurposeSubagentProfile(enabled=False),
    )
    register_harness_profile("openai", profile)
    register_harness_profile(f"openai:{config['model']}", profile)
    backend = LocalShellBackend(
        root_dir="/",
        virtual_mode=True,
        timeout=config["tool_timeout_seconds"],
        env={"PATH": os.environ["PATH"], "HOME": "/tmp", "PYTHONDONTWRITEBYTECODE": "1"},
    )
    agent = create_deep_agent(
        model=model,
        tools=build_tools(input_text),
        system_prompt=SYSTEM_PROMPT,
        middleware=[],
        subagents=[],
        backend=backend,
    )
    prompt = Path("/harness/solver.md").read_text().format(
        input=input_text, skill=Path(SKILL_PATH).read_text().strip()
    )
    budget = config.get("timeout_seconds", 900) * PANEL_BUDGET
    return GroundedAgent(agent, load_answer_space(), budget=budget), prompt

"""Ground the solver's answer in the answer space the frozen memory demonstrates.

The memory is the only evidence the harness has about what a valid answer looks like:
which strings recur as answers, which character joins several answers into one, which
characters an answer may end on, which characters separate pieces *inside* one answer,
and which annotation tags or lead-ins wrap them.  A reply that is a near-miss variant
of a memorised answer (an affix added or dropped, a one-character slip), that carries a
trailing affix the demonstrated answers never carry, or that leaves out a stretch of a
memorised answer around one of its internal separators, scores zero even when the
reasoning behind it was right, so the reply is restored to the memory's own answer
strings before it leaves the harness.
"""

from __future__ import annotations

import json
import re
from pathlib import Path

MEMORY_PATH = "/harness/memory/memory.json"

# Annotation wrappers ("[罪名]...<eoa>", "[DIAGNOSIS]...[/DIAGNOSIS]") are tags, while atom
# brackets inside a SMILES ("[C@@H]", "[n+]") are not: a tag body holds word characters
# only, so chemical notation is never mistaken for markup.
TAG_BODY = r"[A-Za-z0-9_/一-鿿]"
LEAD_TAG = re.compile(rf"^\s*\[{TAG_BODY}{{1,32}}\]")
TRAIL_TAG = re.compile(rf"(\[/?{TAG_BODY}{{1,32}}\]|<[^<>]{{1,32}}>)\s*$")
LEAD_IN = re.compile(r"^\s*[^\s:：\[\]<>]{1,12}[:：]")

# A character only separates answers when the pieces it produces are themselves answers
# (a legal charge list is split by ";", while "、" only ever splits inside one charge).
MIN_PIECE_REUSE = 0.2
# Near misses are repair targets; a larger budget starts rewriting answers that differ.
MAX_EDITS = 1
# A character counts as a separator inside an answer once the memory shows it there more
# than once, so a stray punctuation mark in a single answer demonstrates nothing.
MARKER_MIN_ANSWERS = 2


def strip_annotation(text: str) -> str:
    """Drop the tags and lead-ins a task wraps around an answer."""
    text = (text or "").strip()
    changed = True
    while changed and text:
        changed = False
        match = LEAD_TAG.match(text)
        if match:
            text = text[match.end():].strip()
            changed = True
        match = TRAIL_TAG.search(text)
        if match and match.end() == len(text):
            text = text[: match.start()].strip()
            changed = True
    match = LEAD_IN.match(text)
    if match:
        text = text[match.end():].strip()
    return text


def split_wrapper(text: str) -> tuple[str, str, str]:
    """Split a reply into the leading tag, the body and the trailing tag."""
    text = text or ""
    lead = ""
    match = LEAD_TAG.match(text)
    if match:
        lead = match.group(0)
        text = text[match.end():]
    tail = ""
    match = TRAIL_TAG.search(text)
    if match and match.end() == len(text):
        tail = match.group(0)
        text = text[: match.start()]
    return lead, text, tail


def edit_distance(left: str, right: str, cap: int) -> int:
    """Levenshtein distance, abandoned as soon as it exceeds ``cap``."""
    if abs(len(left) - len(right)) > cap:
        return cap + 1
    previous = list(range(len(right) + 1))
    for i, left_char in enumerate(left, 1):
        current = [i]
        for j, right_char in enumerate(right, 1):
            current.append(min(
                previous[j] + 1,
                current[j - 1] + 1,
                previous[j - 1] + (left_char != right_char),
            ))
        if min(current) > cap:
            return cap + 1
        previous = current
    return previous[-1]


def derive_answer_space(targets: list[str], min_reuse: float = MIN_PIECE_REUSE) -> dict:
    """Infer the answer strings, their endings, their separators from memory."""
    answers = [strip_annotation(target) for target in targets or []]
    answers = [answer for answer in answers if answer]
    if not answers:
        return {"items": [], "separator": None, "endings": [], "markers": ""}
    whole = set(answers)
    separators = {}
    for answer in answers:
        for char in set(answer):
            if not char.isalnum() and not char.isspace():
                separators[char] = separators.get(char, 0) + 1
    best = None
    for char, seen in separators.items():
        if seen < 2:
            continue
        pieces = {piece.strip() for answer in answers if char in answer
                  for piece in answer.split(char) if piece.strip()}
        if len(pieces) < 2:
            continue
        reuse = sum(1 for piece in pieces if piece in whole) / len(pieces)
        if reuse < min_reuse:
            continue
        if best is None or (reuse, seen) > best[0]:
            best = ((reuse, seen), char, pieces)
    if best is None:
        items = sorted(whole)
        return {"items": items, "separator": None, "endings": answer_endings(whole),
                "markers": answer_markers(items)}
    items = sorted(best[2] | whole)
    return {
        "items": items,
        "separator": best[1],
        "endings": answer_endings(items),
        "markers": answer_markers(items),
    }


def answer_endings(answers) -> list[str]:
    """The characters the memory ever lets an answer end on."""
    return sorted({answer[-1] for answer in answers if answer})


def answer_markers(items) -> str:
    """The characters the memory demonstrates as separators inside an answer.

    A demonstrated answer may carry punctuation that never joins answers into a
    list (";" splits a charge list, while "、" sits inside one charge): the memory
    still shows the character sitting between pieces of its own answers, so a
    stretch of an answer that carries one of those characters can be left out
    without the answer becoming a different one.
    """
    seen: dict[str, int] = {}
    for item in items or []:
        for char in set(item or ""):
            if not char.isalnum() and not char.isspace():
                seen[char] = seen.get(char, 0) + 1
    return "".join(sorted(char for char, count in seen.items() if count >= MARKER_MIN_ANSWERS))


def omitted_span(item: str, candidate: str):
    """The one stretch ``candidate`` would have to lose to become ``item``."""
    length = len(candidate) - len(item)
    if length <= 0:
        return None
    shared = 0
    while shared < len(item) and candidate[shared] == item[shared]:
        shared += 1
    for start in range(shared + 1):
        if candidate[start + length:] == item[start:]:
            return candidate[start:start + length]
    return None


def restore_abbreviation(item: str, items, markers: str) -> str:
    """Restore an answer the reply wrote with one stretch of it left out.

    The memory demonstrates answers that carry internal separators, so a reply
    that reproduces a demonstrated answer with one stretch of it — a stretch that
    contains a demonstrated separator — left out is that answer abbreviated, and
    the demonstrated answer is restored.  Only the shortest demonstrated answer
    the reply can be cut down to is restored, and only when it is the only one at
    that length: a reply the memory already demonstrates stands, and a stretch
    that drops no separator ("过失..." -> "...") has dropped a word, not a
    separator, so it is a different answer and is left to the near-miss rule.
    """
    stripped = item.strip()
    if not stripped or not markers or stripped in items:
        return item
    best = None
    tied = False
    for candidate in items:
        span = omitted_span(stripped, candidate)
        if span is None or not any(char in markers for char in span):
            continue
        if best is None or len(candidate) < len(best):
            best, tied = candidate, False
        elif len(candidate) == len(best) and candidate != best:
            tied = True
    return item if best is None or tied else best


def trim_affix(item: str, endings) -> str:
    """Drop a trailing character the demonstrated answers never carry as an ending.

    The memory shows which characters terminate an answer.  A reply that ends an
    answer with some other character, sitting on top of a character the memory does
    end answers with, is carrying an affix that no demonstrated answer carries, so
    the affix goes.  A character the reply itself uses inside the same answer is
    notation rather than an affix ("[C@@H]1CC1" is not trimmed), and a trailing
    character that leaves the answer ending on an undemonstrated character keeps the
    reply intact: the evidence only covers what an ending may look like, not what
    may precede one.
    """
    if not item or not endings:
        return item
    endings = set(endings)
    stripped = item.strip()
    if not stripped or stripped[-1] in endings:
        return item
    trimmed = stripped[:-1].strip()
    if not trimmed or trimmed[-1] not in endings:
        return item
    if stripped[-1] in trimmed:
        return item
    return trimmed


def snap_item(item: str, items: list[str], max_edits: int = MAX_EDITS) -> str:
    """Return the answer string the item is a near miss of, if exactly one exists."""
    item = item.strip()
    if not item or item in items:
        return item
    core = strip_annotation(item)
    if not core:
        return item
    lowered = core.lower()
    best = None
    tied = 0
    for candidate in items:
        distance = edit_distance(lowered, candidate.lower(), max_edits)
        if distance > max_edits:
            continue
        key = (distance, -len(candidate))
        if best is None or key < best[0]:
            best = (key, candidate)
            tied = 1
        elif key == best[0]:
            tied += 1
    return best[1] if best is not None and tied == 1 else item


def ground_answer(text: str, space: dict, max_edits: int = MAX_EDITS) -> str:
    """Rewrite every answer string in a reply that is a near miss of a memorised one."""
    items = (space or {}).get("items")
    if not items or not text:
        return text
    endings = (space or {}).get("endings") or []
    markers = (space or {}).get("markers") or ""
    lead, body, tail = split_wrapper(text)
    separator = (space or {}).get("separator")

    def ground_item(piece: str) -> str:
        return restore_abbreviation(
            snap_item(trim_affix(piece, endings), items, max_edits), items, markers,
        )

    if separator and separator in body:
        body = separator.join(ground_item(piece) for piece in body.split(separator))
    else:
        body = ground_item(body)
    return f"{lead}{body}{tail}"


def _parse_object(text: str):
    """Find the JSON object a reply carries, the way the evaluator reads it."""
    try:
        data = json.loads(text)
    except (json.JSONDecodeError, TypeError):
        data = None
    if isinstance(data, dict):
        return data
    for match in re.finditer(r"```(?:json)?\s*([\s\S]*?)\s*```", text):
        try:
            data = json.loads(match.group(1))
        except json.JSONDecodeError:
            continue
        if isinstance(data, dict):
            return data
    for start in range(len(text)):
        if text[start] != "{":
            continue
        depth, position, in_string = 1, start + 1, False
        while position < len(text) and depth > 0:
            char = text[position]
            if char == '"' and (position == 0 or text[position - 1] != "\\"):
                in_string = not in_string
            elif not in_string:
                depth += 1 if char == "{" else (-1 if char == "}" else 0)
            position += 1
        if depth:
            continue
        try:
            data = json.loads(text[start:position])
        except json.JSONDecodeError:
            continue
        if isinstance(data, dict):
            return data
    return None


def ground_reply(text: str, space: dict, max_edits: int = MAX_EDITS) -> str:
    """Ground the final answer of a solver reply, JSON object or bare label alike."""
    if not text or not (space or {}).get("items"):
        return text
    payload = _parse_object(text)
    if isinstance(payload, dict):
        answer = payload.get("final_answer")
        if not isinstance(answer, str):
            return text
        grounded = ground_answer(answer, space, max_edits)
        if grounded == answer:
            return text
        payload["final_answer"] = grounded
        return json.dumps(payload, ensure_ascii=False)
    # No JSON: only a reply that is itself essentially a label is safe to repair.
    return ground_answer(text.strip(), space, max_edits)


def answer_text(reply: str) -> str:
    """The answer a reply carries: its JSON field when it has one, else the reply itself."""
    payload = _parse_object(reply)
    if isinstance(payload, dict) and isinstance(payload.get("final_answer"), str):
        return payload["final_answer"]
    return (reply or "").strip()


def panel_winner(replies: list[str]) -> int:
    """The index of the reply the panel agrees on.

    An answer is compared the way the memory's wrappers are stripped, so two replies that
    carry the same answer under different markup are one vote.  The most common answer wins
    and the earliest reply carrying it breaks a tie.
    """
    keys = [strip_annotation(answer_text(reply)) for reply in replies]
    counts: dict[str, int] = {}
    for key in keys:
        counts[key] = counts.get(key, 0) + 1
    leader = max(counts, key=lambda key: counts[key])
    return keys.index(leader)


def answers_agree(replies: list[str]) -> bool:
    """True when every reply of the panel carries the same answer."""
    return len({strip_annotation(answer_text(reply)) for reply in replies}) == 1


def load_answer_space(path: str = MEMORY_PATH) -> dict:
    """Derive the answer space of the memory frozen for this task."""
    try:
        memory = json.loads(Path(path).read_text())
    except (OSError, json.JSONDecodeError):
        return {"items": [], "separator": None, "endings": [], "markers": ""}
    examples = memory.get("examples") if isinstance(memory, dict) else memory
    if not isinstance(examples, list):
        return {"items": [], "separator": None, "endings": [], "markers": ""}
    targets = [
        example.get("target", example.get("answer", ""))
        for example in examples if isinstance(example, dict)
    ]
    return derive_answer_space(targets)

"""Offline FewShotAll learning, run separately from the solver."""

import argparse
import json
from pathlib import Path


def prepare_memory(train: list[dict], epochs: int) -> dict:
    examples = []
    for _ in range(epochs):
        for item in train:
            example = {"input": item["input"], "target": item["target"]}
            if "raw_question" in item:
                example["raw_question"] = item["raw_question"]
            examples.append(example)
    return {"examples": examples}


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--train", default="/input/train.json")
    parser.add_argument("--output", default="/output/memory.json")
    parser.add_argument("--epochs", type=int, default=1)
    args = parser.parse_args()
    train = json.loads(Path(args.train).read_text())
    Path(args.output).write_text(json.dumps(prepare_memory(train, args.epochs), indent=2))

"""Fixed solver process entry; receives input and a per-question gateway token."""

import importlib.util
import json
import re
import sys

from langchain_core.callbacks import BaseCallbackHandler
from langchain_openai import ChatOpenAI
from openai import OpenAI

EXPLICIT_CACHE = False


def mark_cache_prefix(messages):
    """Cache the stable prefix and history through the latest message."""
    prefix = [
        index for index, message in enumerate(messages)
        if message.get("role") in {"system", "user"}
    ][:2]
    marked = {*prefix, len(messages) - 1}
    out = []
    for index, message in enumerate(messages):
        if index in marked:
            content = message.get("content")
            if isinstance(content, str):
                message = dict(message, content=[{
                    "type": "text", "text": content,
                    "cache_control": {"type": "ephemeral"},
                }])
            elif isinstance(content, list) and content:
                blocks = [dict(block) if isinstance(block, dict) else block for block in content]
                if isinstance(blocks[-1], dict):
                    blocks[-1]["cache_control"] = {"type": "ephemeral"}
                message = dict(message, content=blocks)
        out.append(message)
    return out


class DeepSeekChatOpenAI(ChatOpenAI):
    """Preserve DeepSeek reasoning across the harness's non-streaming tool turns."""

    def _create_chat_result(self, response, generation_info=None):
        result = super()._create_chat_result(response, generation_info)
        data = response if isinstance(response, dict) else response.model_dump()
        for generation, choice in zip(result.generations, data["choices"]):
            if "reasoning_content" in choice["message"]:
                generation.message.additional_kwargs["reasoning_content"] = choice["message"]["reasoning_content"]
        return result

    def _get_request_payload(self, input_, *, stop=None, **kwargs):
        payload = super()._get_request_payload(input_, stop=stop, **kwargs)
        if "max_completion_tokens" in payload:
            payload["max_tokens"] = payload.pop("max_completion_tokens")
        for message, original in zip(payload["messages"], self._convert_input(input_).to_messages()):
            if original.type == "ai" and "reasoning_content" in original.additional_kwargs:
                message["reasoning_content"] = original.additional_kwargs["reasoning_content"]
        if EXPLICIT_CACHE:
            payload["messages"] = mark_cache_prefix(payload["messages"])
        return payload


def has_final_answer_field(text):
    """True if the response is (or contains) JSON carrying a final_answer field."""
    if not text:
        return False
    try:
        data = json.loads(text)
        if isinstance(data, dict) and "final_answer" in data:
            return True
    except (json.JSONDecodeError, TypeError):
        pass
    return bool(re.search(r'"final_answer"\s*:', text))


def reformat_to_schema(client, model, response):
    """One no-think json_object call to wrap a free-form answer into the schema."""
    result = client.chat.completions.create(
        model=model,
        messages=[
            {"role": "system", "content": "You convert answers into JSON. Output only JSON."},
            {"role": "user", "content": (
                'Convert the following answer into a JSON object with exactly two string'
                ' fields, "reasoning" and "final_answer". Copy the answer content unchanged,'
                ' preserving any required markup such as [DIAGNOSIS]...[/DIAGNOSIS] inside'
                f' final_answer.\n\nAnswer:\n\n{response}'
            )},
        ],
        response_format={"type": "json_object"},
        extra_body={"enable_thinking": False},
    )
    converted = result.choices[0].message.content or ""
    return converted if has_final_answer_field(converted) else response


class ToolTrace(BaseCallbackHandler):
    def on_tool_start(self, serialized, input_str, *, run_id, **kwargs):
        self.emit("tool_start", run_id=str(run_id), name=serialized.get("name"), input=input_str)

    def on_tool_end(self, output, *, run_id, **kwargs):
        value = output.model_dump(mode="json") if hasattr(output, "model_dump") else str(output)
        self.emit("tool_end", run_id=str(run_id), output=value)

    def on_tool_error(self, error, *, run_id, **kwargs):
        self.emit("tool_error", run_id=str(run_id), error=str(error))

    @staticmethod
    def emit(event, **values):
        print(json.dumps({"event": event, **values}, ensure_ascii=False), flush=True)


def main():
    request = json.load(sys.stdin)
    config = request["solver"]
    global EXPLICIT_CACHE
    EXPLICIT_CACHE = bool(config.get("explicit_cache"))
    # The subclass is provider-agnostic: it preserves reasoning_content across tool
    # turns and keeps the wire field as max_tokens, which DashScope (qwen) requires.
    model_class = DeepSeekChatOpenAI if config.get("provider") in {"deepseek", "qwen"} else ChatOpenAI
    model = model_class(
        model=config["model"],
        base_url=request["gateway_url"],
        api_key=request["gateway_token"],
        temperature=config["temperature"],
        max_tokens=config["max_tokens"],
        reasoning_effort=config.get("reasoning_effort"),
        extra_body=config.get("extra_body"),
        timeout=config.get("client_timeout_seconds", config["request_timeout_seconds"]),
        max_retries=0,
        streaming=False,
        use_responses_api=False,
        profile={
            "tool_calling": True,
            "max_input_tokens": config["context_window"],
            "max_output_tokens": config["max_tokens"],
        },
    )
    sys.path.insert(0, "/harness")
    spec = importlib.util.spec_from_file_location("candidate", "/harness/agent.py")
    candidate = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(candidate)
    agent, prompt = candidate.build_agent(model, request["input"], config)
    if config.get("answer_guard"):
        prompt += (
            "\n\nFINAL OUTPUT REQUIREMENT (mandatory, overrides anything else): Your final"
            ' message MUST be a single JSON object with exactly two string fields,'
            ' "reasoning" and "final_answer". Put the answer itself (keeping any required'
            ' markup such as [DIAGNOSIS]...[/DIAGNOSIS]) inside "final_answer". Output'
            " nothing outside the JSON object."
        )
    result = agent.invoke(
        {"messages": [{"role": "user", "content": prompt}]},
        config={"callbacks": [ToolTrace()], "recursion_limit": config["max_model_calls"] * 4 + 20},
    )
    response = result["messages"][-1].content
    if isinstance(response, list):
        response = "".join(block if isinstance(block, str) else block.get("text", "") for block in response)
    if config.get("answer_guard") and not has_final_answer_field(response):
        guard_client = OpenAI(
            base_url=request["gateway_url"], api_key=request["gateway_token"],
            timeout=config["client_timeout_seconds"], max_retries=0,
        )
        response = reformat_to_schema(guard_client, config["model"], response)
